76	impl Eval for ast::Expr<'_> {
77	    type Output = Value;
78	
79	    fn eval(self, vm: &mut Vm) -> SourceResult<Self::Output> {
80	        let span = self.span();
81	        let forbidden = |name| {
82	            error!(span, "{name} is only allowed directly in code and content blocks")
83	        };
84	
85	        let value = match self {
86	            Self::Text(v) => v.eval(vm).map(Value::Content),
87	            Self::Space(v) => v.eval(vm).map(Value::Content),
88	            Self::Linebreak(v) => v.eval(vm).map(Value::Content),
89	            Self::Parbreak(v) => v.eval(vm).map(Value::Content),
90	            Self::Escape(v) => v.eval(vm),
91	            Self::Shorthand(v) => v.eval(vm),
92	            Self::SmartQuote(v) => v.eval(vm).map(Value::Content),
93	            Self::Strong(v) => v.eval(vm).map(Value::Content),
94	            Self::Emph(v) => v.eval(vm).map(Value::Content),
95	            Self::Raw(v) => v.eval(vm).map(Value::Content),
96	            Self::Link(v) => v.eval(vm).map(Value::Content),
